class ChangePasswordScreen extends StatefulWidget {const ChangePasswordScreen({super.key});@override State<ChangePasswordScreen> createState()=>_ChangePasswordScreenState();}
class _ChangePasswordScreenState extends State<ChangePasswordScreen>{final current=TextEditingController(),password=TextEditingController(),confirm=TextEditingController();bool busy=false,hide=true;@override void dispose(){current.dispose();password.dispose();confirm.dispose();super.dispose();}Future<void>_save()async{if(password.text.length<8||password.text!=confirm.text){showSnack(context,password.text!=confirm.text?'Passwords do not match.':'Use at least 8 characters.',error:true);return;}setState(()=>busy=true);try{await SessionScope.of(context).api.patch('/profile',body:{'current_password':current.text,'password':password.text,'password_confirmation':confirm.text});if(mounted){showSnack(context,'Password updated.');Navigator.of(context).pop();}}on ApiException catch(e){if(mounted)showSnack(context,e.message,error:true);}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext context)=>AbsPage(title:'Change Password',subtitle:'Protect your ABS account',child:ListView(children:[TextField(controller:current,obscureText:true,decoration:const InputDecoration(labelText:'Current password')),const SizedBox(height:10),TextField(controller:password,obscureText:hide,decoration:InputDecoration(labelText:'New password',helperText:'8+ characters with upper/lower case and a number.',suffixIcon:IconButton(onPressed:()=>setState(()=>hide=!hide),icon:Icon(hide?Icons.visibility_outlined:Icons.visibility_off_outlined)))),const SizedBox(height:10),TextField(controller:confirm,obscureText:true,decoration:const InputDecoration(labelText:'Confirm new password')),const SizedBox(height:14),ElevatedButton(onPressed:busy?null:_save,child:Text(busy?'Updating...':'Update password'))]));}
